/**
 * Sayfa tipi + pathname ile index kararı. Sitemap ve SEOHead ortak kaynak.
 *
 * @typedef {object} SeoPageInput
 * @property {string} [pathname] — useLocation pathname
 * @property {boolean} [isTmdb] — TMDB / IMDb API ile üretilen içerik
 * @property {boolean} [isAutoGenerated] — fikstür/API ile otomatik üretilen detay vb.
 * @property {number} [contentLength] — düz metin karakter sayısı (HTML strip sonrası); thin içerik için
 * @property {boolean} [forceIndex] — editoryal/whitelist sayfalar için açık allow sinyali
 * @property {boolean} [isEditorialCategory] — curated kategori sayfası bayrağı (bilgi amaçlı)
 */

import { categoriesTR, categoriesDE } from '../data/whatToWatchCategories.js';
import { BLOG_TRANSLATIONS_DE } from '../data/staticBlogTranslationsDE.js';

/** Blog / uzun form içerik için thin eşiği (düz metin karakter) */
export const MIN_CONTENT_THRESHOLD = 280;

/**
 * Curated "Ne İzlesem" kategori slug'ları — data source'tan türetilir; senkron kalır.
 * Detay (:id) rotaları ile çakışan regex'lerin curated sayfaları yanlışlıkla
 * noindex'lemesini engellemek için whitelist olarak kullanılır.
 */
const CURATED_TR_SLUGS = new Set(Object.keys(categoriesTR || {}));
const CURATED_DE_SLUGS = new Set(Object.keys(categoriesDE || {}));

/**
 * @param {SeoPageInput} [page]
 * @returns {boolean} true → robots noindex önerilir
 */
export function shouldNoIndex(page = {}) {
  if (page?.forceIndex === true) return false;
  if (page?.isTmdb === true) return true;
  if (page?.isAutoGenerated === true) return true;
  const len = page?.contentLength;
  if (typeof len === 'number' && len >= 0 && len < MIN_CONTENT_THRESHOLD) return true;

  const pathname = page?.pathname ?? page?.path;
  if (pathname && pathnameMatchesNoindexPolicy(pathname)) return true;
  return false;
}

/**
 * Sadece path; Üst bileşenler pathname’i iletebilir.
 * @param {string} [pathname]
 */
export function pathnameShouldNoindex(pathname) {
  return shouldNoIndex({ pathname });
}

/**
 * @param {string} pathname
 */
export function pathnameMatchesNoindexPolicy(pathname) {
  const path = (pathname || '/').split('?')[0];
  const norm = path.replace(/\/+$/, '') || '/';

  if (/^\/yonetim(\/|$)/.test(path)) return true;
  if (/^\/admin(\/|$)/.test(path)) return true;
  if (norm === '/admin-login') return true;
  if (norm === '/musteri-kayit') return true;
  if (/^\/search(\/|$)/.test(path)) return true;

  if (/^\/blog\/write(\/|$)/.test(path)) return true;

  /* Çevrilmemiş /de/blog/:slug kopyaları: noindex,follow (prerender sözleşmesi).
     Sitemap ve SPA Helmet aynı politikadan beslenir. TR /blog/:slug index kalır.
     Statik Almanca çevirisi mevcut olan yazılar indexlenir. */
  const deBlogMatch = norm.match(/^\/de\/blog\/([^/]+)$/);
  if (deBlogMatch) {
    const slug = deBlogMatch[1];
    if (BLOG_TRANSLATIONS_DE && BLOG_TRANSLATIONS_DE[slug]) {
      return false;
    }
    return true;
  }

  if (/^\/mac-programi\/[^/]+$/.test(norm)) return true;
  if (/^\/mac-takvimi\/[^/]+$/.test(norm)) return true;
  if (norm === '/spor-gundemi' || /^\/spor-gundemi\//.test(norm)) return true;
  if (/^\/de\/spielplan\/[^/]+$/.test(norm)) return true;

  if (/^\/film\/[^/]+$/.test(norm)) return true;
  if (/^\/dizi\/[^/]+$/.test(norm)) return true;

  /* Liste (/ne-izlesem, /de/was-soll-ich-schauen) index; sadece dinamik detay :id noindex.
     Curated kategori slug'ları whitelist üzerinden hariç tutulur — data source ile senkron. */
  {
    const trDetail = norm.match(/^\/ne-izlesem\/([^/]+)$/);
    if (trDetail && !CURATED_TR_SLUGS.has(trDetail[1])) return true;

    const wtwDetail = norm.match(/^\/what-to-watch\/([^/]+)$/);
    if (wtwDetail) return true;

    const deDetail = norm.match(/^\/de\/was-soll-ich-schauen\/([^/]+)$/);
    if (deDetail && !CURATED_DE_SLUGS.has(deDetail[1])) return true;
  }

  return false;
}

/** HTML veya zengin metinden yaklaşık düz metin uzunluğu */
export function plainTextLengthFromHtml(html) {
  if (html == null || typeof html !== 'string') return 0;
  const stripped = html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return stripped.length;
}
